    public static class StefanŻeromski
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Chłopy polskie – to tchórze nad tchórzami.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Człowiek mądry nie uważa śmierci za rzeczywistość godną myślenia. Przedmiotem myślenia filozoficznego może być tylko życie.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Jak kwiat człowiek powstaje i skruszon bywa…", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Ani chwili tracić darmo nie wolno!", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Czyż to nie wielkość ducha, aby nie cofnąć ręki przed tym, od czego ludzie uciekają z całej siły?", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Dziś coraz bardziej rozwijająca się myśl usuwa po trochu wszystkie niedorzeczne fantazje, a na ich miejsce wprowadza kwestie rzeczywiście filozoficznej wartości i każe wróżyć wiele o myślicielu już w osiemnastym roku.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Ekscytacje rodzą ekscytacje i padam w „delirium tremens” – marzenia.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Kobieta pozwoli ze sobą zrobić, co zechcesz, bylebyś jej o tym nie mówił.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Kochając, marzy się o przyszłości – ja wspominam przeszłość.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Ludzkość musi przejrzeć – musi! Głupota średniowieczna wiecznie trwać nie może – to nie podobna!", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Marzenia moje przyjdą więc może do skutku: choć okruszyną uznania wypłacą mu się może przecie.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Myśl wielka, a mianowicie stosująca się do posłuszeństwa względem starszych i rodziców, ukryta jest w formie bajki; całe życie człowieka lekkomyślnego przeprowadzone jest pod obrazem nieposłusznego radom ojca młodzieńca.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Najmniej znacząca dla innego okoliczność mnie o sercowe łzy przyprawia.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Obejdę świat dookoła, a może zabiję bijące mnie serce – kalejdoskoskie.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Po mowie jest na świecie potęgą największą – milczenie.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Przyjaźń wygląda przy uczuciu do kobiety jak świeca łojowa przy świetle elektrycznym.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Są chwile, że wszystko na mnie uderza, wszystko się łamie w rękach, wszystko zawodzi. Skądś niespodzianie zjawiają się bóle i targają serce.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Szczęście moje mieści się w wyrazie: wolność. Gdybym teraz odebrał sobie życie – nikt nie uroniłby po mnie łzy żalu.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Walka z miłością to walka niemal z życiem, bo miłość jest życia rdzeniem.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "My, lekarze! My, sól ziemi, my, rozum, my ręka kojąca wszelką boleść...", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Kto zmaga się ze światem, zginąć musi w czasie, by żyć w wieczności.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Bo czyliż najnędzniejszy ze wszystkich, najlichszy kwiatuszek może się rozwinąć w lodowni?", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Tęsknota, tęsknota… Uczucie najbardziej niewypowiedziane, stan próżny wszelakiej ulgi, ucisk serca ciągły i jednostajny.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Złe niewątpliwie jest tylko jedno: krzywda bliźniego. Człowiek – jest to rzecz święta, której krzywdzić nikomu nie wolno.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Prawdę swą należy mówić głośno, nie schlebiając ani – żal się Boże! – gwelfom i gibelinom polskim, ani rzeczom, ani wypadkom, ani stosunkom, ani ideom.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Gdybyś kiedy we śnie poczuła, że oczy moje już nie patrzą na ciebie z miłością, wiedz, żem żyć przestał.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Nauka jest jak niezmierne morze… Im więcej jej pijesz, tym bardziej jesteś spragniony. Kiedyś poznasz, jaka to jest rozkosz… Ucz się, co tylko jest sił w tobie, żeby jej zakosztować!", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Trza było skazać na śmierć tę miłość, od której serce pęka, jakby zbielałem w ogniu żelazem wypalić wszystko aż do ostatniego wspomnienia.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Była w tej pani jakaś cecha otwartości, która nakłania do uczuć przyjaznych.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Cezary jeszcze się w nikim nie kochał, ale wiedział, że taka pozycja istnieje i jest w modzie.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Gdzież są twoje szklane domy?", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Każdy ma swoje miejsce ulubione w dzieciństwie. To jest ojczyzna duszy.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Nie będzie już przenigdy Prusak niemczył Kaszuby!", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Polecił tłumaczowi, żeby powiedział Kaszubie, iż podoba się panu jego opowieść.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Szczęście nie znosi za sobą pościgu. Napastowane – odwraca się i zaczyna prześladować napastnika.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Trzeba rozrywać rany polskie, żeby się nie zabliźniły błoną podłości.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Im kultura niższa, tym naśladownictwo bardziej rozwinięte.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Łańcuch niewolniczy pokochasz po roku, spokojny kąt i dobrych ludzi po miesiącu.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Na pięść, jako argument, bywa też pięść argumentem.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Piękno życia jest tylko w pracy.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Przydałoby się mniej ''Te Deum'', a więcej oleum.", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Żałuję dziś bardzo, że nie umiem matematyki. Jest to nauka piękna – ja nie umiem uchwycić przewodniej myśli, jaka się śród formuł przewija. […] Umiem tylko i lubię arytmetykę. Do reszty – mam łeb tępy jak karp!", Author = "Stefan Żeromski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Stefan_Żeromski", Text = "Życie jest trudną lekcją, której nie można się nauczyć. Trzeba ją przeżyć.", Author = "Stefan Żeromski" },
        };
    }
}